style.css:
@-moz-document domain("khanacademy.org") {
:root { color-scheme: dark !important; }

  /* ====================================================================
     Wonder Blocks design tokens — Khan drives almost every surface,
     border and text color through these CSS custom properties, so
     retoning them at :root re-themes the bulk of the app at once.
     Light neutrals -> dark palette; learning/mastery/brand tokens are
     left untouched below to preserve meaning.
     ==================================================================== */
  :root {
    /* Surfaces */
    --wb-semanticColor-core-background-base-default: #14181d !important;
    --wb-semanticColor-core-background-base-subtle: #1c2128 !important;
    --wb-semanticColor-core-background-base-strong: #0d1117 !important;
    --wb-semanticColor-core-background-disabled-default: #1c2128 !important;
    --wb-semanticColor-core-background-disabled-strong: #262c33 !important;
    --wb-semanticColor-core-background-neutral-subtle: #1c2128 !important;
    --wb-semanticColor-feedback-neutral-subtle-background: #1c2128 !important;
    --wb-semanticColor-status-neutral-background: #1c2128 !important;
    --wb-semanticColor-chonky-disabled-background-primary: #1c2128 !important;
    --wb-semanticColor-chonky-disabled-background-secondary: #1c2128 !important;

    /* Inputs */
    --wb-semanticColor-input-default-background: #1a1f26 !important;
    --wb-semanticColor-input-readOnly-background: #1a1f26 !important;
    --wb-semanticColor-input-disabled-background: #181c22 !important;
    --wb-semanticColor-input-default-border: #3a424c !important;
    --wb-semanticColor-input-readOnly-text: #c4cdd6 !important;
    --wb-semanticColor-input-disabled-foreground: #717880 !important;

    /* Subtle blue "info / notice" tints used for banners + selected nav */
    --wb-semanticColor-feedback-info-subtle-background: #18222f !important;
    --wb-semanticColor-status-notice-background: #18222f !important;
    --wb-semanticColor-core-background-instructive-subtle: #18222f !important;
    --wb-semanticColor-chonky-progressive-background-secondary-rest: #18222f !important;
    --wb-semanticColor-chonky-progressive-background-secondary-hover: #1d2a3a !important;
    --wb-semanticColor-chonky-progressive-background-secondary-press: #1d2a3a !important;
    --wb-semanticColor-chonky-progressive-background-secondary-selected: #1d2a3a !important;

    /* Text */
    --wb-semanticColor-core-foreground-neutral-strong: #e6edf3 !important;
    --wb-semanticColor-core-foreground-neutral-subtle: #9aa4af !important;
    --wb-semanticColor-feedback-neutral-subtle-text: #c4cdd6 !important;
    --wb-semanticColor-feedback-info-subtle-text: #c4cdd6 !important;
    --wb-semanticColor-status-neutral-foreground: #c4cdd6 !important;
    --wb-semanticColor-input-error-foreground: #e6edf3 !important;

    /* Borders / dividers (soften the bright default greys) */
    --wb-semanticColor-core-border-neutral-default: #2d333b !important;
    --wb-semanticColor-core-border-neutral-strong: #3a424c !important;
    --wb-semanticColor-chonky-neutral-border-secondary-rest: #2d333b !important;
    --wb-semanticColor-chonky-neutral-border-secondary-hover: #3a424c !important;
    --wb-semanticColor-feedback-neutral-subtle-border: #2d333b !important;
    --wb-semanticColor-core-shadow-chonky-neutral-subtle: #2d333b !important;

    /* Brand blue: refine the raw Khan link/CTA blue (#1865f2) so it reads
       well on near-black instead of glowing harshly */
    --wb-semanticColor-core-foreground-instructive-default: #5fb0e6 !important;
    --wb-semanticColor-core-foreground-instructive-strong: #9bd4ff !important;
    --wb-semanticColor-chonky-progressive-foreground-secondary-rest: #5fb0e6 !important;
    --wb-semanticColor-action-secondary-progressive-hover-foreground: #9bd4ff !important;
    --wb-semanticColor-status-notice-foreground: #5fb0e6 !important;
    --wb-semanticColor-link-hover: #9bd4ff !important;

    /* Primary CTA buttons keep the Khan blue identity but are deepened a
       touch so they sit on the dark UI and white button text reads clean */
    --wb-semanticColor-action-primary-progressive-default-background: #2563c9 !important;
    --wb-semanticColor-action-primary-progressive-hover-background: #2f6fd6 !important;
    --wb-semanticColor-action-primary-progressive-press-background: #1d51b0 !important;
    --wb-semanticColor-core-background-instructive-default: #2563c9 !important;
    --wb-semanticColor-core-background-instructive-strong: #1d51b0 !important;

    /* Mastery / progress: keep the meaningful "attempted" (gold) and
       "complete" (green) states; only the empty "not started" square is
       remapped from light grey to a dark grey so it reads as empty on the
       dark grid instead of glowing white */
    --wb-semanticColor-learning-background-progress-notStarted-default: #2d333b !important;
    --wb-semanticColor-learning-foreground-progress-notStarted-strong: #8b949e !important;
  }

  /* ====================================================================
     Base surfaces
     ==================================================================== */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  #react-root, [data-test-id="learn-menu"] { background-color: transparent !important; }

  /* ====================================================================
     Legacy "bibliotron" header (hardcoded white, stable class on
     article/exercise pages — not token driven)
     ==================================================================== */
  .bibliotron-header,
  .white-outer-wrapper,
  .clearfix.bibliotron-header { background-color: #0d1117 !important; }
  .bibliotron-header a,
  .bibliotron-header span,
  .bibliotron-header div { color: #e6edf3 !important; }

  /* ====================================================================
     Top navigation bar
     ==================================================================== */
  nav[role="navigation"], header[role="banner"] { background-color: #0d1117 !important; }

  /* ====================================================================
     Headings + body text
     Khan ships dark-on-light body copy through hardcoded atomic color
     classes that bypass the design tokens, so plain text tags need an
     enforced light color. Inline-colored spans (links, badges, mastery
     labels) keep their own color via the more specific rules below.
     ==================================================================== */
  h1, h2, h3, h4, h5, h6 { color: #e6edf3 !important; }
  /* Home "Explore" subject grid: each category header is an accordion toggle
     button whose label is a direct text node hardcoded to a near-black
     (rgb(33,36,44)) that bypasses the token remaps, leaving the subject titles
     ("Math: Pre-K - 8th grade", "Computing", "Test prep" …) ~1.04 contrast on
     the dark grid. Stable scope: the only aria-expanded buttons under
     #main-content. */
  #main-content button[aria-expanded] { color: #e6edf3 !important; }
  p, li, label, dd, dt, blockquote, figcaption, td, th, caption,
  legend, article, section, main { color: #c4cdd6 !important; }
  span:not([class*="color"]):not([style*="color"]) { color: inherit; }

  /* ====================================================================
     Links — keep Khan blue identity, refined for dark
     ==================================================================== */
  a { color: #5fb0e6; }
  a:hover { color: #9bd4ff; }

  /* ====================================================================
     Exercise "Report a problem" button — Khan hardcodes its label to a
     dark navy (rgba(33,36,44,.64)) that bypasses the Wonder Blocks token
     remaps, leaving it dark-on-dark (~1.04 contrast) at the foot of the
     exercise card. Scoped to the stable exercise-chrome wrapper (its only
     button) and lifted to a readable muted light.
     ==================================================================== */
  .exercise-chrome-content-for-mobile-zoom button { color: #9aa4af !important; }
  .exercise-chrome-content-for-mobile-zoom button:hover { color: #c4cdd6 !important; }

  /* ====================================================================
     Discussion tabs ("Questions" / "Tips & Thanks") under articles and
     videos. Khan hardcodes the active tab to the raw brand blue (#1865f2,
     ~3.7:1 on near-black) and the inactive tab to a mid grey (#717378,
     ~3.8:1) via -webkit-text-fill-color, both bypassing the Wonder Blocks
     token remaps and landing dark-on-dark. Scoped to the stable ARIA tab
     ids; lift the inactive label to a readable muted light and the active
     one to the theme's refined Khan blue. Set text-fill too (fill drives
     the rendered color, so color alone would not stick). */
  #questions-tab, #comments-tab {
    color: #9aa4af !important; -webkit-text-fill-color: #9aa4af !important;
  }
  #questions-tab[aria-selected="true"], #comments-tab[aria-selected="true"] {
    color: #5fb0e6 !important; -webkit-text-fill-color: #5fb0e6 !important;
  }

  /* ====================================================================
     Search box (header) — white-on-white in light theme
     ==================================================================== */
  input[type="search"],
  input[type="text"],
  input[type="email"],
  input[type="password"],
  input[type="number"],
  input[type="tel"],
  input[type="url"],
  textarea,
  input[placeholder*="earch"] {
    background-color: #1a1f26 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  input::placeholder, textarea::placeholder { color: #8b949e !important; opacity: 1 !important; }

  /* ====================================================================
     Hardcoded light surfaces that bypass the design tokens
     (some cards/sections set white or pale-grey directly, not via a var)
     ==================================================================== */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background-color:#fff"],
  [style*="background-color: #fff"],
  [style*="background-color: var(--wb-semanticColor-core-foreground-knockout"] {
    background-color: #1c2128 !important;
  }

  /* Content-area neutralizer — the robust catch for surfaces that hardcode
     white / pale-blue through hashed atomic classes (the logged-out
     "Welcome to Khan Academy" onboarding banner, the homepage audience
     pills + course band, search result/facet cards, and the CS course
     "Create / View programs" promo tiles). All page content lives under
     the stable `#main-content` wrapper, so we flatten stray light surfaces
     onto the dark page there. No `!important`, so it overrides the hashed
     atomic-class backgrounds (which aren't important) while still yielding
     to the token-driven dark surfaces and the `!important` rules below —
     deploy-durable, no per-hash targeting. The `background-image:none` kills the
     white "more content below" scroll-fade overlay (a hardcoded
     `linear-gradient(transparent -> white)` on a hashed div at the foot of the
     scrollable unit sidebar) which the color-only neutralizer otherwise misses;
     Khan paints no decorative gradients in `#main-content` (mastery/progress use
     solid tokens + SVG strokes), so this is safe. The `:not(span)` carve-out is
     essential: Khan's mastery legend keys (Mastered/Quiz/Unit test…) and the
     unit-progress grid markers are Wonder Blocks icon `<span>`s rendered as a
     `mask-image` SVG whose FILL is the span's own `background-color` (the slate
     mastery tone, white, or `currentColor`). Flattening that to transparent
     stripped every icon to an empty box; excluding `span` keeps the mastery /
     progress colors intact (no large light-surface span exists to need it). */
  #main-content [class]:not(span) { background-color: transparent; background-image: none; }
  /* Keep interactive promo cards/buttons reading as tappable cards */
  #main-content button[class],
  #main-content a[class][role],
  #main-content [role="button"] { background-color: #1c2128; }
  #main-content button[class]:hover,
  #main-content a[class][role]:hover,
  #main-content [role="button"]:hover { background-color: #232a32; }

  /* Search-result content-type icons (article / video / exercise glyphs).
     Khan renders each as a `mask-image` SVG on a 24px span inside a 48px ringed
     circle, colouring the glyph through the span's `background-color` (natively a
     dark ink rgba(33,36,44,.64)). That ink is dark-on-dark on the theme AND the
     `#main-content [class]` neutraliser flattens it to transparent, so the glyph
     vanishes and every result shows an empty ring. The circle carries a stable
     (deterministic vanilla-extract) class; restore a muted light icon colour on
     its masked span so the content type reads again. Degrades safely — if the
     hashed class ever changes the icon simply stays empty as before, no breakage. */
  ._1yakn8cj span { background-color: #8b949e !important; }

  /* Mastery "information" glyphs (the small "i" beside "… possible mastery
     points" and each unit's "Unit mastery: NN%" indicator) are the same
     `mask-image` icon pattern, hardcoded to a dark ink (rgba(33,36,44,.64))
     built for the light page, so they read dark-on-dark here. Scoped to the
     stable accessible name (not a hashed class) and lifted to a muted light so
     the mastery affordance stays visible. */
  #main-content span[role="img"][aria-label="Mastery information"] { background-color: #8b949e !important; }

  /* Logged-out donation widget (form/fieldset of amount + frequency options
     render on white) — neutralized via its stable form structure. The
     selected option keeps a clear highlighted state in the brand blue. */
  form fieldset, form fieldset ul, form fieldset li,
  form fieldset li label { background-color: #1c2128 !important; color: #c4cdd6 !important; }
  form fieldset li label:hover { background-color: #232a32 !important; }

  /* OneTrust cookie-consent banner (logged-out, first visit) — Khan loads the
     stock OneTrust CMP, whose container, body text and "Cookies Settings"
     outline button hardcode white / near-black built for a light page, leaving
     a glaring white modal (and a near-invisible light-grey "Use of cookies"
     heading on white). Not token-driven, so it bypasses every remap above.
     Dark the OneTrust surfaces via its stable #onetrust-* ids; the blue
     Accept/Reject buttons keep the Khan-blue brand identity. */
  #onetrust-consent-sdk #onetrust-banner-sdk,
  #onetrust-consent-sdk #onetrust-pc-sdk,
  #onetrust-consent-sdk .ot-sdk-container,
  #onetrust-consent-sdk .ot-pc-footer { background-color: #1c2128 !important; }
  #onetrust-consent-sdk #onetrust-policy-title,
  #onetrust-consent-sdk #onetrust-policy-text,
  #onetrust-consent-sdk .ot-b-addl-desc,
  #onetrust-consent-sdk #onetrust-banner-sdk *:not(a):not(button) { color: #e6edf3 !important; }
  #onetrust-consent-sdk #onetrust-banner-sdk a { color: #5fb0e6 !important; }
  #onetrust-consent-sdk #onetrust-pc-btn-handler,
  #onetrust-consent-sdk .ot-pc-refuse-all-handler {
    background-color: #1c2128 !important;
    color: #5fb0e6 !important;
    border-color: #3a424c !important;
  }

  /* ====================================================================
     Soften any remaining bright borders across the app
     ==================================================================== */
  * { border-color: #2d333b !important; }

  /* ====================================================================
     Code editor / syntax highlighting (CS & programming courses)
     CodeMirror + ka-syntax tokens, kept readable on dark
     ==================================================================== */
  .CodeMirror, .CodeMirror-gutters,
  pre, code, .highlight, .codehilite {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }
  .CodeMirror-gutters { border-color: #2d333b !important; }
  .CodeMirror-linenumber { color: #6e7681 !important; }
  .cm-comment { color: #8b949e !important; }
  .cm-keyword, .cm-builtin { color: #ff7b72 !important; }
  .cm-string, .cm-string-2 { color: #a5d6ff !important; }
  .cm-number, .cm-atom { color: #79c0ff !important; }
  .cm-variable, .cm-variable-2, .cm-property { color: #e6edf3 !important; }
  .cm-def, .cm-tag { color: #7ee787 !important; }
  .cm-attribute { color: #79c0ff !important; }
  .cm-operator { color: #c4cdd6 !important; }

  /* Khan's "scratchpad" code editor is ACE (class .ace_editor.ace-tm), not
     CodeMirror, so the palette above never reaches it. ACE ships its light
     "tm" theme whose token colors (blue keywords, dark-blue numbers, dark-green
     strings, navy functions, black cursor) are built for a white background and
     read poorly once the editor surface is dark; the generic span rule above
     also flattens every token to one light grey, wiping out highlighting.
     Re-theme ACE on dark with the same GitHub-dark palette as CodeMirror. */
  .ace_editor, .ace_editor .ace_gutter, .ace_editor .ace_scroller {
    background-color: #0d1117 !important;
  }
  .ace_editor, .ace_editor .ace_gutter-cell { color: #e6edf3 !important; }
  .ace_editor .ace_comment { color: #8b949e !important; }
  .ace_editor .ace_keyword, .ace_editor .ace_storage { color: #ff7b72 !important; }
  .ace_editor .ace_string { color: #a5d6ff !important; }
  .ace_editor .ace_constant, .ace_editor .ace_constant.ace_numeric,
  .ace_editor .ace_constant.ace_language, .ace_editor .ace_constant.ace_buildin {
    color: #79c0ff !important;
  }
  .ace_editor .ace_support.ace_function,
  .ace_editor .ace_entity.ace_name.ace_function { color: #d2a8ff !important; }
  .ace_editor .ace_support.ace_type, .ace_editor .ace_support.ace_class,
  .ace_editor .ace_support.ace_constant { color: #79c0ff !important; }
  .ace_editor .ace_variable, .ace_editor .ace_identifier { color: #e6edf3 !important; }
  .ace_editor .ace_keyword.ace_operator, .ace_editor .ace_punctuation,
  .ace_editor .ace_paren { color: #c4cdd6 !important; }
  .ace_editor .ace_invalid { color: #ffa198 !important; }
  /* Cursor + line/selection chrome (the universal border rule otherwise dims
     the caret to #2d333b, leaving it nearly invisible). */
  .ace_editor .ace_cursor { color: #e6edf3 !important; border-left-color: #e6edf3 !important; }
  .ace_editor .ace_marker-layer .ace_active-line,
  .ace_editor .ace_gutter-active-line { background-color: #161b22 !important; }
  .ace_editor .ace_marker-layer .ace_selection { background-color: #2d4f7c !important; }
  .ace_editor .ace_print-margin { background-color: #21262d !important; }

  /* ====================================================================
     Worked-example math highlight colors (MathML `mathcolor`)
     Khan tints terms in step-by-step solutions with a fixed palette built
     for a white page: a grey for annotation labels ("Replace a with …"),
     plus muted red/blue/green/purple term highlights. On the dark surface the
     grey is dark-on-dark (~1.3 contrast) and the muted hues dim out. Remap
     each to a lighter shade of the SAME hue so the pedagogical meaning (this
     term is "the red one", that one "the blue one") is preserved while staying
     legible on dark. Targets the `mathcolor` carrier and its descendants. */
  [mathcolor="#5D5F66"], [mathcolor="#5D5F66"] * { color: #9aa4af !important; }
  [mathcolor="#D92916"], [mathcolor="#D92916"] * { color: #ff7b72 !important; }
  [mathcolor="#3D7586"], [mathcolor="#3D7586"] * { color: #6cb6d9 !important; }
  [mathcolor="#0C7F99"], [mathcolor="#0C7F99"] * { color: #6cb6d9 !important; }
  [mathcolor="#11ACCD"], [mathcolor="#11ACCD"] * { color: #79c0ff !important; }
  [mathcolor="#208170"], [mathcolor="#208170"] * { color: #7ee787 !important; }
  [mathcolor="#0D923F"], [mathcolor="#0D923F"] * { color: #7ee787 !important; }
  [mathcolor="#7854AB"], [mathcolor="#7854AB"] * { color: #d2a8ff !important; }
  [mathcolor="#9D38BD"], [mathcolor="#9D38BD"] * { color: #d2a8ff !important; }
  [mathcolor="#CA337C"], [mathcolor="#CA337C"] * { color: #ff8ac4 !important; }
  [mathcolor="#E07D10"], [mathcolor="#E07D10"] * { color: #f0a868 !important; }
  /* Perseus exercise answer-choice tints (a muted green + mauve used to
     colour the multiple-choice math on practice pages) hardcode dark values
     built for the white page and land ~3.5:1 on the dark surface. Lift each
     to the lighter same-hue shade already used for the worked-example set. */
  [mathcolor="#447A53"], [mathcolor="#447A53"] * { color: #7ee787 !important; }
  [mathcolor="#B25071"], [mathcolor="#B25071"] * { color: #ff8ac4 !important; }

  /* Article content tables: Khan renders some data/function tables with
     hardcoded pale cells (rgb(247,248,250)) on classless <td>/<th>, which the
     `#main-content [class]` neutralizer cannot reach. Flatten them to the dark
     page; borders are already softened by the universal border rule. */
  #main-content table, #main-content thead, #main-content tbody,
  #main-content tr, #main-content td, #main-content th {
    background-color: transparent !important;
  }

  /* Perseus exercise multiple-choice cards: each choice `li` draws its card
     frame/divider through `::before` + `::after` pseudo-elements hardcoded to
     a light grey (rgb(219,220,221)) built for the white page — invisible to an
     element-bg audit, but they render as bright white frames around the (dark)
     answer cards here. Remap the pseudo fills to the theme's border tone so the
     choices read as subtle dark cards. Scoped to the stable Perseus renderer
     class so nothing else is touched. */
  .framework-perseus li::before,
  .framework-perseus li::after,
  .perseus-renderer li::before,
  .perseus-renderer li::after { background-color: #2d333b !important; }

  /* Perseus "choose all / choose 1" answer cards were rendering as empty dark
     boxes — only the A-E letter tile showed, the math statement inside each card
     was invisible. Root cause: the logged-out donation-form rule above
     (`form fieldset …`) is broad enough to also match the Perseus choice
     <fieldset> (choices are grouped inside a <form>), painting an opaque #1c2128
     onto the choice fieldset/ul/li. Perseus renders each choice's block math
     (a MathJax `mjx-container` given compensating negative margins) on a lower
     paint layer, so that opaque fill covered the math — the letters (drawn on a
     separate button) stayed visible. Reset the Perseus choice containers to
     transparent so the math paints again; the cards keep their dark look from the
     surrounding exercise surface. Higher specificity than the `form fieldset`
     rule, so it wins without touching the donation widget. */
  .framework-perseus fieldset, .framework-perseus fieldset ul,
  .framework-perseus fieldset li, .framework-perseus fieldset li label,
  .perseus-renderer fieldset, .perseus-renderer fieldset ul,
  .perseus-renderer fieldset li, .perseus-renderer fieldset li label {
    background-color: transparent !important;
  }

  /* ====================================================================
     Scrollbars
     ==================================================================== */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #14181d; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
}
